package com.example

/**
 * Complete, distinct 20 cards for Mathematics Sets 10 to 15 (120 unique cards).
 * Covers Circle Theorems, Congruence & Similarity, Probability, Statistics, Commercial Math, and Matrices & Sets.
 */
object FlashcardBankMathsSetsPart2 {

  fun getMathSet(setNum: Int, cardNum: Int): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      10 -> mathSet10[(c - 1) % mathSet10.size]
      11 -> mathSet11[(c - 1) % mathSet11.size]
      12 -> mathSet12[(c - 1) % mathSet12.size]
      13 -> mathSet13[(c - 1) % mathSet13.size]
      14 -> mathSet14[(c - 1) % mathSet14.size]
      15 -> mathSet15[(c - 1) % mathSet15.size]
      16 -> mathSet16[(c - 1) % mathSet16.size]
      17 -> mathSet17[(c - 1) % mathSet17.size]
      18 -> mathSet18[(c - 1) % mathSet18.size]
      19 -> mathSet19[(c - 1) % mathSet19.size]
      20 -> mathSet20[(c - 1) % mathSet20.size]
      else -> null
    }
  }

  // --- SET 10: වෘත්ත ප්‍රමේයයන් & ස්පර්ශක ---
